[CmdletBinding()]param([string]$MSADPTRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$o=Join-Path $MSADPTRoot 'Invoke-MSADPT.ps1';$r=Get-Content (Join-Path $MSADPTRoot 'Catalogs\module-registry.json') -Raw|ConvertFrom-Json;$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($o,[ref]$t,[ref]$e);if(@($e).Count){throw ($e.Message-join'; ')};$cmd=Get-Command $o;if('IncludeKerberosCrypto' -notin $cmd.Parameters.Keys){throw 'IncludeKerberosCryptoMissing'};if('IncludeKdcTelemetry' -notin $cmd.Parameters.Keys){throw 'IncludeKdcTelemetryMissing'};if(@($r.Modules|Where-Object ModuleId -eq 'Invoke-MSADPTKerberosCryptographicPosture').Count-ne1){throw 'RegistryEntryMissing'};[pscustomobject]@{Status='Passed';ParserErrorCount=0;RegistryEntryCount=1;ResumeMarkerPresent=([IO.File]::ReadAllText($o)-match 'KerberosCryptoComplete');ReportMarkerPresent=([IO.File]::ReadAllText($o)-match 'Kerberos Cryptographic Posture')}
